#include "spi_nor_stm32wba.h"
#include <assert.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
typedef struct {uint32_t now; unsigned count; uint8_t sr1,sr2,last; bool selected;} Fake;
static bool cs(void*v,bool active){Fake*f=v;assert(f->selected!=active);f->selected=active;return true;}
static bool xfer(void*v,const uint8_t*tx,uint8_t*rx,size_t size,uint32_t timeout){Fake*f=v;assert(f->selected&&timeout);f->count++;if(tx&&rx){assert(size==2);rx[0]=0;rx[1]=(tx[0]==5)?f->sr1:f->sr2;} else if(tx){assert(size==1);f->last=tx[0];}return true;}
static uint32_t now(void*v){return ((Fake*)v)->now;}static void delay(void*v,uint32_t n){((Fake*)v)->now+=n;}
static companion_spi_nor_stm32wba_t make(Fake*f,unsigned phase,bool active,bool failed,bool supported){companion_spi_nor_stm32wba_t n={0};n.config.target=COMPANION_SPI_NOR_STM32WBA_TARGET_WBA55;n.config.chip_select=cs;n.config.transfer=xfer;n.config.now_ms=now;n.config.delay_ms=delay;n.config.context=f;n.config.transfer_timeout_ms=200;n.info.jedec_id=0xef6018;n.info.size_bytes=16777216;n.probed=true;n.erase_active=active;n.erase_command_failed=failed;n.erase_suspend_supported=supported;n.erase_phase=(uint8_t)phase;n.erase_started_ms=11;n.erase_pause_started_ms=13;n.erase_phase_started_ms=17;n.erase_run_since_ms=19;n.suspend_wait_ms=2;n.resume_guard_ms=2;return n;}
int main(void){unsigned cases=0;for(unsigned phase=0;phase<5;phase++)for(unsigned sr1=0;sr1<4;sr1++)for(unsigned sus=0;sus<2;sus++)for(unsigned flags=0;flags<8;flags++){Fake a={0},b={0};a.now=b.now=100;a.sr1=b.sr1=(uint8_t)sr1;a.sr2=b.sr2=sus?0x80:0;companion_spi_nor_stm32wba_t x=make(&a,phase,(flags&1)!=0,(flags&2)!=0,(flags&4)!=0),y=make(&b,phase,(flags&1)!=0,(flags&2)!=0,(flags&4)!=0);companion_spi_nor_stm32wba_status_t u=companion_spi_nor_stm32wba_erase_suspend_step(&x),v=companion_spi_nor_stm32wba_erase_suspend_step_bounded(&y,8);if(u!=v||x.erase_active!=y.erase_active||x.erase_phase!=y.erase_phase||x.erase_command_failed!=y.erase_command_failed||x.erase_pause_started_ms!=y.erase_pause_started_ms||x.erase_started_ms!=y.erase_started_ms||x.erase_phase_started_ms!=y.erase_phase_started_ms||x.erase_run_since_ms!=y.erase_run_since_ms||a.count!=b.count||a.last!=b.last||a.selected!=b.selected){printf("DIFF phase=%u sr1=%u sus=%u flags=%u old=%d new=%d calls=%u/%u phase=%u/%u\n",phase,sr1,sus,flags,(int)u,(int)v,a.count,b.count,x.erase_phase,y.erase_phase);return 1;}cases++;}printf("PASS %u status/owner state combinations match original when no timing fault is injected\n",cases);return 0;}
